// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _check(uint256 initial, uint256 newval) internal {
        try c.SetMinSum(initial) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.SetMinSum(newval) {} catch { return; }
        uint256 observed;
        try c.MinSum() returns (uint256 __r) { observed = __r; } catch { return; }
        assertTrue(observed == initial);
    }

    function testFuzz_check(uint256 initial, uint256 newval) public {
        _check(initial, newval);
    }

    receive() external payable {}
}
